renewalScriptTemplate:
#Requires -RunAsAdministrator
# The agent provides certificate.pfx and its password. For a manual run, export the PFX from HomeCA into this folder.
$certificate = Import-HomeCACertificate certificate.pfx
Import-Module WebAdministration
$rebound = 0
foreach ($binding in @(Get-WebBinding -Protocol https)) {
    $hash = $binding.certificateHash
    if (-not $hash -or $hash -eq $certificate.Thumbprint) { continue }
    $previous = Get-Item -LiteralPath ('Cert:\LocalMachine\' + $binding.certificateStoreName + '\' + $hash) -ErrorAction SilentlyContinue
    if (-not $previous -or $previous.Subject -ne $certificate.Subject) { continue }
    Add-HomeCARestoreStep ('Import-Module WebAdministration; (Get-WebBinding -Protocol https | Where-Object { $_.bindingInformation -eq ' + (ConvertTo-HomeCALiteral $binding.bindingInformation) + ' }).AddSslCertificate(' + (ConvertTo-HomeCALiteral $hash) + ', ' + (ConvertTo-HomeCALiteral $binding.certificateStoreName) + ')')
    $binding.AddSslCertificate($certificate.Thumbprint, 'My')
    Write-Output "homeca-install: $($binding.bindingInformation) now uses $($certificate.Thumbprint)"
    $rebound++
}
if ($rebound -eq 0) { Write-Output "homeca-install: no HTTPS binding uses a certificate for $($certificate.Subject); assign it once in IIS Manager" }

#Requires -RunAsAdministrator
# The agent provides certificate.pfx and its password. For a manual run, export the PFX from HomeCA into this folder.
$certificate = Import-HomeCACertificate certificate.pfx
# The Remote Desktop service runs as NETWORK SERVICE and needs read access to the private key.
$rsa = [Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($certificate)
$container = $null
if ($rsa -is [Security.Cryptography.RSACryptoServiceProvider]) { $container = $rsa.CspKeyContainerInfo.UniqueKeyContainerName }
elseif ($rsa.Key.Provider.Provider -eq 'Microsoft Software Key Storage Provider') { $keyFile = Join-Path $env:ProgramData ('Microsoft\Crypto\Keys\' + $rsa.Key.UniqueName) }
else {
    # A CryptoAPI key behind RSACng: its file name comes from the CSP, not from the CNG unique name.
    $parameters = New-Object Security.Cryptography.CspParameters ($(if ($rsa.Key.Provider.Provider -like '*AES*') { 24 } else { 1 }), $rsa.Key.Provider.Provider, $rsa.Key.KeyName)
    $parameters.Flags = [Security.Cryptography.CspProviderFlags]'UseExistingKey,UseMachineKeyStore'
    $container = (New-Object Security.Cryptography.RSACryptoServiceProvider $parameters).CspKeyContainerInfo.UniqueKeyContainerName
}
if ($container) { $keyFile = Join-Path $env:ProgramData ('Microsoft\Crypto\RSA\MachineKeys\' + $container) }
if (-not (Test-Path -LiteralPath $keyFile)) { throw "homeca-install: private key file $keyFile not found" }
& icacls.exe $keyFile /grant '*S-1-5-20:R' | Out-Null
if ($LASTEXITCODE -ne 0) { throw "homeca-install: could not grant NETWORK SERVICE read access to $keyFile" }
$listener = Get-CimInstance -Namespace root\cimv2\TerminalServices -ClassName Win32_TSGeneralSetting -Filter "TerminalName='RDP-Tcp'"
if (-not $listener) { throw 'homeca-install: the RDP-Tcp listener was not found' }
if ($listener.SSLCertificateSHA1Hash -ne $certificate.Thumbprint) {
    Add-HomeCARestoreStep ('Get-CimInstance -Namespace root\cimv2\TerminalServices -ClassName Win32_TSGeneralSetting -Filter "TerminalName=''RDP-Tcp''" | Set-CimInstance -Property @{ SSLCertificateSHA1Hash = ' + (ConvertTo-HomeCALiteral $listener.SSLCertificateSHA1Hash) + ' }')
    $listener | Set-CimInstance -Property @{ SSLCertificateSHA1Hash = $certificate.Thumbprint }
}
Write-Output "homeca-install: RDP-Tcp now uses $($certificate.Thumbprint)"
